def factorial(n):
    # Check if n is less than 0, as the factorial function isn't defined for negative integers.
    if n < 0:
        return ValueError("Factorial is not defined for negative integers")

    # If n is 0 or 1, return 1 as 0! and 1! both equal 1.
    if n == 0 or n == 1:
        return 1

    # Recursive case: n! is n times (n-1)!.
    else:
        return n * factorial(n-1)

