def can_form_palindrome(s):
    # Create a frequency counter
    freq_dict = {}
    for char in s:
        freq_dict[char] = freq_dict.get(char, 0) + 1

    # Count number of characters with odd frequency
    odd_counts = sum(1 for count in freq_dict.values() if count % 2)

    # Check if string length is even and all characters have even count
    # OR string length is odd and there is exactly one character with odd count
    if (len(s) % 2 == 0 and odd_counts == 0) or (len(s) % 2 and odd_counts == 1):
        return True
    else:
        return False

